curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{}' | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for u in data['members']:
        name = u.get('real_name', '') or u.get('profile', {}).get('display_name', '')
        if 'maya' in name.lower() or 'chen' in name.lower():
            print(f\"{u['id']} - {name} - {u.get('profile',{}).get('real_name','')}\")
else:
    print('Error:', data)
"
